const test = require('node:test');
const assert = require('node:assert/strict');
const _ = require('../lodash');

test('comparison.test.cjs', () => {
  assert.strictEqual(_.gt(3, 1), true);
  assert.strictEqual(_.gt(1, 3), false);
  assert.strictEqual(_.gt(3, 3), false);
});

test('coerces numeric and string operands', () => {
  assert.strictEqual(_.gt('10', 2), true);
  assert.strictEqual(_.gt(2, '10'), false);
  assert.strictEqual(_.gt('2', '10'), true);
});

test('handles NaN and ordinary numeric boundaries', () => {
  assert.strictEqual(_.gt(NaN, 0), false);
  assert.strictEqual(_.gt(0, NaN), false);
  assert.strictEqual(_.gt(Infinity, Number.MAX_VALUE), true);
  assert.strictEqual(_.gt(-0, 0), false);
});

